def f(v, nd=2):
    if v is None or (isinstance(v, float) and v != v): return "n/a"
    if isinstance(v, bool): return "yes" if v else "no"
    if isinstance(v, (list, tuple)): return "[" + ", ".join(f(x, nd) for x in v) + "]"
    if isinstance(v, int): return f"{v:,}"
    if isinstance(v, float): return f"{v:,.{nd}f}"
    return str(v)


def md(rows, cols, nd=None):
    nd = nd or {}
    out = ["| " + " | ".join(c for c in cols) + " |", "|" + "---|" * len(cols)]
    for r in rows: out.append("| " + " | ".join(f(r.get(c), nd.get(c, 2)) for c in cols) + " |")
    return "\n".join(out)


def rule_text(ifs): return " and ".join(f"`{c} {o} {json.dumps(v) if isinstance(v, list) else v}`" for c, o, v in ifs)


